%w[636:375 636:1246 636:1328 636:1345 636:1395].each { |id| abort("missing node #{id}") unless s.include?(id) }
%w[PrinterMenu.cpp SetupCommands ConfigWizard IPrinterRecognitionService].each { |term| abort("missing #{term}") unless s.include?(term) }
